// Self-checking testbench for skid_buffer. Two lanes: WIDTH 8 and WIDTH 1.
// A queue model of up to two beats is checked against the outputs every cycle.
module skid_buffer_tb;

    reg        clk;
    reg        rst_n;
    reg        s_valid;
    reg        m_ready;
    reg  [7:0] s_data;

    wire       s_ready8;
    wire       m_valid8;
    wire [7:0] m_data8;
    wire       s_ready1;
    wire       m_valid1;
    wire [0:0] m_data1;

    skid_buffer #(.WIDTH(8)) dut8 (
        .clk     (clk),
        .rst_n   (rst_n),
        .s_valid (s_valid),
        .s_ready (s_ready8),
        .s_data  (s_data),
        .m_valid (m_valid8),
        .m_ready (m_ready),
        .m_data  (m_data8)
    );

    skid_buffer #(.WIDTH(1)) dut1 (
        .clk     (clk),
        .rst_n   (rst_n),
        .s_valid (s_valid),
        .s_ready (s_ready1),
        .s_data  (s_data[0:0]),
        .m_valid (m_valid1),
        .m_ready (m_ready),
        .m_data  (m_data1)
    );

    // Scoreboard and model state.
    integer         passed;
    integer         failed;
    integer         accepted;
    integer         delivered;
    integer         dropped;
    integer         mcnt;
    integer         base;
    integer         i;
    reg             known;
    reg             stalled;
    reg  [7:0]      mq0;
    reg  [7:0]      mq1;
    reg  [7:0]      held_data;
    reg  [31:0]     rng;
    reg  [8*64-1:0] nonce;

    task chk;
        input            cond;
        input [8*56-1:0] what;
        begin
            if (cond === 1'b1) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("check failed at %0t: %0s", $time, what);
            end
        end
    endtask

    task next_rand;
        begin
            rng = rng ^ (rng << 13);
            rng = rng ^ (rng >> 17);
            rng = rng ^ (rng << 5);
        end
    endtask

    task chk_ready_steady;
        input sr_ref;
        begin
            if (known) begin
                chk(s_ready8 === sr_ref, "s_ready does not move within a cycle");
                chk(s_ready1 === sr_ref, "W1 s_ready does not move within cycle");
            end
        end
    endtask

    // One clock cycle: check outputs, glitch the inputs, clock, update the model.
    task tick;
        reg       sr_ref;
        reg       p_sfire;
        reg       p_mfire;
        reg       p_rst;
        reg       p_mv;
        reg       p_mr;
        reg [7:0] p_sd;
        reg [7:0] p_md;
        begin
            #1;
            if (known) begin
                chk(m_valid8 === (mcnt != 0), "m_valid high exactly while beats held");
                chk(s_ready8 === (mcnt < 2), "s_ready high exactly while <2 held");
                chk(m_valid1 === m_valid8, "W1 m_valid agrees with W8");
                chk(s_ready1 === s_ready8, "W1 s_ready agrees with W8");
                if (mcnt != 0) begin
                    chk(m_data8 === mq0, "m_data is the oldest held beat");
                    chk(m_data1 === mq0[0:0], "W1 m_data is the oldest held beat");
                end
                if (stalled) begin
                    chk((m_valid8 === 1'b1) && (m_data8 === held_data),
                        "stalled beat stays offered unchanged");
                end
            end
            // s_ready must not follow s_valid or m_ready inside a cycle.
            sr_ref = s_ready8;
            s_valid = ~s_valid;
            #1;
            chk_ready_steady(sr_ref);
            m_ready = ~m_ready;
            #1;
            chk_ready_steady(sr_ref);
            s_valid = ~s_valid;
            #1;
            chk_ready_steady(sr_ref);
            m_ready = ~m_ready;
            #1;
            chk_ready_steady(sr_ref);

            p_rst   = rst_n;
            p_mv    = m_valid8;
            p_mr    = m_ready;
            p_md    = m_data8;
            p_sd    = s_data;
            p_sfire = s_valid & s_ready8;
            p_mfire = m_valid8 & m_ready;

            clk = 1'b1;
            #1;
            if (p_rst !== 1'b1) begin
                dropped = dropped + mcnt;
                mcnt    = 0;
                known   = 1'b1;
                stalled = 1'b0;
            end else if (known) begin
                if (p_mfire === 1'b1) begin
                    if (mcnt == 0) begin
                        chk(1'b0, "a beat left an empty slice");
                    end else begin
                        mq0       = mq1;
                        mcnt      = mcnt - 1;
                        delivered = delivered + 1;
                    end
                end
                if (p_sfire === 1'b1) begin
                    if (mcnt >= 2) begin
                        chk(1'b0, "a beat was accepted into a full slice");
                    end else begin
                        if (mcnt == 0) begin
                            mq0 = p_sd;
                        end else begin
                            mq1 = p_sd;
                        end
                        mcnt     = mcnt + 1;
                        accepted = accepted + 1;
                    end
                end
                stalled   = p_mv & ~p_mr;
                held_data = p_md;
            end
            #3;
            clk = 1'b0;
            #1;
        end
    endtask

    initial begin
        passed    = 0;
        failed    = 0;
        accepted  = 0;
        delivered = 0;
        dropped   = 0;
        mcnt      = 0;
        base      = 0;
        known     = 1'b0;
        stalled   = 1'b0;
        mq0       = 8'h00;
        mq1       = 8'h00;
        held_data = 8'h00;
        rng       = 32'h1234_5678;
        clk       = 1'b0;
        rst_n     = 1'b0;
        s_valid   = 1'b0;
        m_ready   = 1'b0;
        s_data    = 8'h00;
        if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0) begin
            nonce = {64{8'h00}};
        end

        // 1. Reset values (a beat offered during reset is not taken).
        s_valid = 1'b1;
        s_data  = 8'hEE;
        tick;
        tick;
        rst_n   = 1'b1;
        s_valid = 1'b0;
        chk((m_valid8 === 1'b0) && (m_valid1 === 1'b0), "reset: m_valid low");
        chk((s_ready8 === 1'b1) && (s_ready1 === 1'b1), "reset: s_ready high");
        tick;
        chk(m_valid8 === 1'b0, "reset: slice stays idle");

        // 2. One-cycle latency.
        s_valid = 1'b1;
        s_data  = 8'hA5;
        m_ready = 1'b1;
        chk(m_valid8 === 1'b0, "latency: nothing offered before accept");
        tick;
        s_valid = 1'b0;
        chk((m_valid8 === 1'b1) && (m_data8 === 8'hA5), "latency: beat offered after accept edge");
        tick;
        chk(m_valid8 === 1'b0, "latency: slice empty after beat leaves");

        // 3. Long stream at full throughput.
        base    = delivered;
        m_ready = 1'b1;
        s_valid = 1'b1;
        s_data  = 8'h00;
        for (i = 0; i < 64; i = i + 1) begin
            chk(s_ready8 === 1'b1, "throughput: s_ready high every cycle");
            if (i > 0) begin
                chk(m_valid8 === 1'b1, "throughput: m_valid high, no bubble");
            end
            tick;
            s_data = s_data + 8'd1;
        end
        chk(delivered - base == 63, "throughput: one beat out per edge");
        s_valid = 1'b0;
        tick;
        chk(delivered - base == 64, "throughput: all 64 beats delivered");
        chk(m_valid8 === 1'b0, "throughput: idle after the stream");

        // 4. Stall with one beat held, then two, then release.
        m_ready = 1'b0;
        s_valid = 1'b1;
        s_data  = 8'hB1;
        tick;
        chk((s_ready8 === 1'b1) && (m_valid8 === 1'b1) && (m_data8 === 8'hB1),
            "stall: one held, second may enter");
        s_data = 8'hB2;
        tick;
        chk((s_ready8 === 1'b0) && (m_data8 === 8'hB1), "stall: two held, s_ready low");
        for (i = 0; i < 6; i = i + 1) begin
            next_rand;
            s_data  = rng[7:0];
            s_valid = rng[8];
            tick;
            chk((s_ready8 === 1'b0) && (m_valid8 === 1'b1) && (m_data8 === 8'hB1),
                "stall: full slice holds, third refused");
        end
        s_valid = 1'b0;
        m_ready = 1'b1;
        tick;
        chk((m_valid8 === 1'b1) && (m_data8 === 8'hB2) && (s_ready8 === 1'b1),
            "stall: ready rises, second beat next");
        tick;
        chk((m_valid8 === 1'b0) && (s_ready8 === 1'b1), "stall: drained in order");

        // 5. Stream with one-cycle and multi-cycle stalls.
        s_valid = 1'b1;
        s_data  = 8'h40;
        for (i = 0; i < 80; i = i + 1) begin
            m_ready = ~((i == 10) || ((i >= 20) && (i < 26)) || (i == 40) || (i == 41)
                        || ((i >= 60) && (i < 70)));
            tick;
            if (s_ready8 === 1'b1) begin
                s_data = s_data + 8'd1;
            end
        end
        s_valid = 1'b0;
        m_ready = 1'b1;
        tick;
        tick;
        tick;
        chk((mcnt == 0) && (m_valid8 === 1'b0), "stalled stream drains to idle");

        // 6. Reset with two beats held, then with one, then recovery.
        m_ready = 1'b0;
        s_valid = 1'b1;
        s_data  = 8'hC1;
        tick;
        s_data = 8'hC2;
        tick;
        chk((m_valid8 === 1'b1) && (s_ready8 === 1'b0), "reset test: two beats held");
        rst_n   = 1'b0;
        s_data  = 8'hC3;
        m_ready = 1'b1;
        tick;
        rst_n   = 1'b1;
        s_valid = 1'b0;
        chk((m_valid8 === 1'b0) && (s_ready8 === 1'b1) && (m_valid1 === 1'b0)
            && (s_ready1 === 1'b1), "reset with two held drops them");
        tick;
        chk(m_valid8 === 1'b0, "after reset slice stays idle");
        m_ready = 1'b0;
        s_valid = 1'b1;
        s_data  = 8'hD1;
        tick;
        s_valid = 1'b0;
        chk(m_valid8 === 1'b1, "reset test: one beat held");
        rst_n = 1'b0;
        tick;
        rst_n = 1'b1;
        chk((m_valid8 === 1'b0) && (s_ready8 === 1'b1), "reset with one held drops it");
        s_valid = 1'b1;
        s_data  = 8'h3C;
        m_ready = 1'b1;
        tick;
        s_valid = 1'b0;
        chk((m_valid8 === 1'b1) && (m_data8 === 8'h3C), "after reset a new beat passes");
        tick;
        chk(m_valid8 === 1'b0, "after reset beat leaves once");

        // 7. Random traffic against the model, with a reset during traffic.
        for (i = 0; i < 4000; i = i + 1) begin
            next_rand;
            s_data = rng[7:0];
            if ((i >= 1000) && (i < 1100)) begin
                s_valid = (rng[15:8] < 8'd200);
                m_ready = (rng[23:16] < 8'd20);
            end else if ((i >= 3000) && (i < 3100)) begin
                s_valid = 1'b1;
                m_ready = 1'b1;
            end else begin
                s_valid = (rng[15:8] < 8'd179);
                m_ready = (rng[23:16] < 8'd153);
            end
            rst_n = (i != 2000);
            tick;
        end
        rst_n   = 1'b1;
        s_valid = 1'b0;
        m_ready = 1'b1;
        tick;
        tick;
        tick;
        chk((mcnt == 0) && (m_valid8 === 1'b0) && (s_ready8 === 1'b1), "random: drains to idle");
        chk(accepted == delivered + dropped, "every accepted beat left once or reset");
        chk(accepted > 1000, "random: traffic actually flowed");

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
=== END FILE ===
